	 */
	function SavePkcs8EncryptedPemFile($password,$path) {
		return CkPrivateKey_SavePkcs8EncryptedPemFile($this->_cPtr,$password,$path);
	}

	/**
	 * Saves the key as unencrypted PKCS #8 DER at ARG1. PKCS #8 is an algorithm-independent private-key container. Chilkat emits the classic version-0 PrivateKeyInfo structure, with the algorithm-specific private-key DER in an OCTET STRING.PrivateKeyInfo ::= SEQUENCE {     version                   Version,     privateKeyAlgorithm       AlgorithmIdentifier,     privateKey                OCTET STRING,     attributes           [0]  IMPLICIT Attributes OPTIONAL }File behavior: An existing destination file is replaced. Parent directories are not created; the parent directory must already exist. macOS Keychain: Starting in Chilkat v10.0.0, ARG1 may be formatted as keychain:<label> to save the private key to the Apple Keychain. Security note: The file contains cleartext private-key material.
